      {made !== null && (
        <>
          {' '}Made <span data-testid="plan-generated-count">{made}</span>
        </>
      )}
      {error && (
        <p role="alert" data-testid="plan-generate-error">
          {error}
        </p>
      )}
    </section>
  );
}

